Create src/lib/emoji.ts (new file — this is a client-usable pure-data module, not server-only, since the picker runs client-side):
```ts
import raw from 'emojibase-data/en/data.json';
import messages from 'emojibase-data/en/messages.json';

export type EmojiEntry = { emoji: string; label: string; tags: string[]; group: number };

export const EMOJIS: EmojiEntry[] = (raw as { emoji: string; label: string; tags?: string[]; group?: number }[])
	.filter((e) => e.group !== undefined)
	.map((e) => ({ emoji: e.emoji, label: e.label, tags: e.tags ?? [], group: e.group! }));

export const GROUPS: { key: number; label: string }[] = (
	messages as { groups: { message: string }[] }
).groups.map((g, i) => ({ key: i, label: g.message }));

export function search_emoji(q: string): EmojiEntry[] {
	const needle = q.trim().toLowerCase();
	if (!needle) return EMOJIS;
	return EMOJIS.filter(
		(e) => e.label.includes(needle) || e.tags.some((t) => t.includes(needle))
	);
}
```
(The `.filter((e) => e.group !== undefined)` drops the ~200 "component" entries like bare skin-tone modifiers and regional-indicator letters seen in the raw data sample, which have `type:1` and no `group` — these aren't standalone sendable emoji, filtering them out keeps the picker to real, complete emoji only; verify this filter's exact boundary by running `node -e "console.log(require('emojibase-data/en/data.json').filter(e=>e.group===undefined).length)"` after installing, and adjust the filter predicate if it's excluding entries that should be included, before wiring the picker component against it.)

