```ts
export async function toggle_reaction(
	env: QEnv,
	uid: string,
	msg_id: string,
	emoji: string
): Promise<Record<string, string[]>> {
	await ensure(env);
	const pt = await retrieve_one(env, msg_id);
	if (!pt || pt.payload?.s !== 'm') throw new Error('not found');
	const m = pt.payload as unknown as Message;
	const rx = { ...(m.rx ?? {}) };
	const set = new Set(rx[emoji] ?? []);
	if (set.has(uid)) set.delete(uid);
	else set.add(uid);
	if (set.size) rx[emoji] = [...set];
	else delete rx[emoji];
	await set_payload(env, msg_id, { rx });
	return rx;
}
```
`retrieve_one`, `set_payload`, `ensure` already imported in chat.ts. Toggle semantics (react again to remove) match WhatsApp's own behavior for a user tapping their own existing reaction.

