```ts
import { json, error } from '@sveltejs/kit';
import type { RequestHandler } from './$types';
import { env } from '$env/dynamic/private';
import { toggle_reaction, get_message } from '$lib/server/chat';
import { is_member } from '$lib/server/group';

export const POST: RequestHandler = async ({ params, request, locals }) => {
	if (!locals.user) throw error(401, 'auth');
	const { emoji } = (await request.json().catch(() => ({}))) as { emoji?: string };
	if (!emoji) throw error(400, 'emoji required');
	const m = await get_message(env, params.id);
	if (!m) throw error(404, 'not found');
	const uid = locals.user.id;
	const allowed = m.gr ? await is_member(env, locals.x2_ws, m.gr, uid) : m.f === uid || m.t === uid;
	if (!allowed) throw error(403, 'not a participant');
	const rx = await toggle_reaction(env, uid, params.id, emoji);
	locals.bg(
		relay_reaction(env, locals.x2_ws, m, params.id, rx).catch(() => {})
	);
	return json({ rx });
};

async function relay_reaction(env: unknown, ws: Fetcher, m: { gr?: string; f: string; t: string }, id: string, rx: Record<string, string[]>) {
	const members = m.gr ? undefined : undefined; // filled below per branch
	await ws.fetch('https://x2-ws/relay', {
		method: 'POST',
		headers: { 'content-type': 'application/json' },
		body: JSON.stringify(
			m.gr
				? { type: 'reaction', id, group: m.gr, rx }
				: { type: 'reaction', id, to: m.f === m.t ? m.f : undefined, members: [m.f, m.t], rx }
		)
	});
}
```
(The `relay_reaction` member-targeting for the 1:1 branch needs the actual counterpart resolution — re-derive from `get_message`'s returned `m.f`/`m.t` directly: for a 1:1 message, both participants must receive the reaction relay, so `members: [m.f, m.t]` is correct as shown, matching `ws/src/relay.ts`'s existing `body.members ?? [body.to]` fan-out convention already used by `/api/send`'s relay call — read that call site (send/+server.ts's `relay()` helper and its `members`/`to` usage, lines 13-23 and 62-82/101-121) to match its exact shape rather than the sketch above, which simplifies the target-resolution; the group branch's `group: m.gr` similarly should match send's `members: g.members.filter(...)` pattern — fetch `g.members` via `get_group(env, m.gr)` if the relay needs an explicit member list rather than a `group` key, matching whatever `build_relay_payload`/`relay()` actually expects for delivery, confirmed by reading `ws/src/relay.ts` and `hub.ts` before finalizing this handler.)

